def total_ventes(chemin):
    lignes = open(chemin).readlines()
    montants = [float(l.split(";")[2])
                for l in lignes]
    return sum(montants)

def premiers_pairs(nombres, n):
    resultat = []
    for x in nombres:
        if x % 2 == 0:
            resultat.append(x)
    return resultat[:n]
